16	
17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.Collection;
21	import java.util.List;
22	
23	import org.springframework.http.HttpHeaders;
24	import org.springframework.http.HttpStatus;
25	import org.springframework.http.ResponseEntity;
26	import org.springframework.samples.petclinic.mapper.OwnerMapper;
27	import org.springframework.samples.petclinic.mapper.PetMapper;
28	import org.springframework.samples.petclinic.mapper.VisitMapper;
29	import org.springframework.samples.petclinic.model.Owner;
30	import org.springframework.samples.petclinic.model.Pet;
31	import org.springframework.samples.petclinic.model.Visit;
32	import org.springframework.samples.petclinic.rest.api.OwnersApi;
33	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
34	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
35	import org.springframework.samples.petclinic.rest.dto.PetDto;
36	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
37	import org.springframework.samples.petclinic.rest.dto.VisitDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
39	import org.springframework.samples.petclinic.rest.validation.AddressNormalizer;
40	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
41	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
42	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
43	import org.springframework.samples.petclinic.rest.validation.EmailNormalizer;
44	import org.springframework.samples.petclinic.rest.validation.FutureRegistrationDateException;
45	import org.springframework.samples.petclinic.rest.validation.InvalidPostcodeException;
46	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
47	import org.springframework.samples.petclinic.rest.validation.PostcodeValidator;
48	import org.springframework.samples.petclinic.rest.validation.OwnerFieldsValidator;
49	import org.springframework.samples.petclinic.rest.validation.TelephoneNormalizer;
50	import org.springframework.samples.petclinic.service.ClinicService;
51	import org.springframework.samples.petclinic.service.OwnerAuditor;
52	import org.springframework.samples.petclinic.util.HouseholdIdGenerator;
53	import org.springframework.samples.petclinic.util.RegistrationDatePolicy;
54	import org.springframework.security.access.prepost.PreAuthorize;
55	import org.springframework.web.bind.annotation.CrossOrigin;
56	import org.springframework.web.bind.annotation.RequestMapping;
57	import org.springframework.web.bind.annotation.RestController;
58	import org.springframework.web.util.UriComponentsBuilder;
59	
60	import jakarta.transaction.Transactional;
61	
62	/**
63	 * @author Vitaliy Fedoriv
64	 */
65	
66	@RestController
67	@CrossOrigin(exposedHeaders = "errors, content-type")
68	@RequestMapping("/api")
69	public class OwnerRestControllerV1 implements OwnersApi {
70	
71	    /**
72	     * Maximum number of owners a single city may hold. A create request whose city already contains
73	     * this many owners is rejected as a conflict.
74	     */
75	    static final int MAX_OWNERS_PER_CITY = 50;
76	
77	    /**
78	     * Maximum number of owners that may be registered on a single day. A create request whose
79	     * registration date already holds this many owners is rejected with 429 Too Many Requests.
80	     */
81	    static final int MAX_OWNERS_PER_DAY = 100;
82	
83	    /**
84	     * Number of owners that may be registered on the current business day before a create/read
85	     * response flags {@code bulkSignupWarning}. Once more than this many owners exist for the day,
86	     * the warning is raised.
87	     */
88	    static final int BULK_SIGNUP_WARNING_THRESHOLD = 80;
89	
90	    private final ClinicService clinicService;
91	
92	    private final OwnerMapper ownerMapper;
93	
94	    private final PetMapper petMapper;
95	
96	    private final VisitMapper visitMapper;
97	
98	    private final OwnerAuditor ownerAuditor;
99	
100	    public OwnerRestControllerV1(ClinicService clinicService,
101	                                 OwnerMapper ownerMapper,
102	                                 PetMapper petMapper,
103	                                 VisitMapper visitMapper,
104	                                 OwnerAuditor ownerAuditor) {
105	        this.clinicService = clinicService;
106	        this.ownerMapper = ownerMapper;
107	        this.petMapper = petMapper;
108	        this.visitMapper = visitMapper;
109	        this.ownerAuditor = ownerAuditor;
110	    }
111	
112	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
113	    @Override
114	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
115	        Collection<Owner> owners;
116	        if (lastName != null) {
117	            owners = this.clinicService.findOwnerByLastName(lastName);
118	        } else {
119	            owners = this.clinicService.findAllOwners();
120	        }
121	        if (owners.isEmpty()) {
122	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
123	        }
124	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
125	    }
126	
127	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
128	    @Override
129	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
130	        Owner owner = this.clinicService.findOwnerById(ownerId);
131	        if (owner == null) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(toOwnerDtoWithBulkSignupWarning(owner), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
140	        ownerFieldsDto.setAddress(AddressNormalizer.normalize(ownerFieldsDto.getAddress()));
141	        List<String> missingFields = OwnerFieldsValidator.findMissingFields(ownerFieldsDto);
142	        if (!missingFields.isEmpty()) {
143	            throw new MissingOwnerFieldsException(missingFields);
144	        }
145	        HttpHeaders headers = new HttpHeaders();
146	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
147	        if (!PostcodeValidator.isValidForCity(owner.getCity(), owner.getPostcode())) {
148	            throw new InvalidPostcodeException(owner.getPostcode(), owner.getCity());
149	        }
150	        if (this.clinicService.countOwnersByCity(owner.getCity()) >= MAX_OWNERS_PER_CITY) {
151	            throw new CityCapacityExceededException(owner.getCity());
152	        }
153	        if (RegistrationDatePolicy.isAfterServerDate(owner.getRegistrationDate())) {
154	            throw new FutureRegistrationDateException(owner.getRegistrationDate());
155	        }
156	        LocalDate registrationDate = RegistrationDatePolicy.effectiveDate(owner.getRegistrationDate());
157	        if (this.clinicService.countOwnersRegisteredOn(registrationDate) >= MAX_OWNERS_PER_DAY) {
158	            throw new DailyOwnerLimitExceededException(registrationDate);
159	        }
160	        owner.setTelephone(TelephoneNormalizer.normalize(owner.getTelephone()));
161	        owner.setEmail(EmailNormalizer.normalize(owner.getEmail()));
162	        // The household is keyed on (last name, postcode): the id is deterministic, so owners with
163	        // the same last name and postcode share it automatically.
164	        owner.setHouseholdId(HouseholdIdGenerator.generate(owner.getLastName(), owner.getPostcode()));
165	        boolean declaredHouseholdMember = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
166	        owner.setDeclaredHouseholdMember(declaredHouseholdMember);
167	        // A second owner in an existing household is a duplicate, unless it declares shared
168	        // membership — in which case it is created as a known household member.
169	        if (!declaredHouseholdMember && this.clinicService.isHouseholdDuplicate(owner)) {
170	            throw new DuplicateIdentityException(owner.getIdentityKey());
171	        }
172	        this.clinicService.saveOwner(owner);
173	        this.ownerAuditor.ownerCreated(owner);
174	        OwnerDto ownerDto = toOwnerDtoWithBulkSignupWarning(owner);
175	        headers.setLocation(UriComponentsBuilder.newInstance()
176	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
177	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
178	    }
179	
180	    /**
181	     * Map an owner to its DTO and stamp {@code bulkSignupWarning}, which reflects whether more than
182	     * {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners have already been registered on the current
183	     * business day.
184	     */
185	    private OwnerDto toOwnerDtoWithBulkSignupWarning(Owner owner) {
186	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
187	        LocalDate today = RegistrationDatePolicy.effectiveDate(null);
188	        ownerDto.setBulkSignupWarning(
189	            this.clinicService.countOwnersRegisteredOn(today) > BULK_SIGNUP_WARNING_THRESHOLD);
190	        return ownerDto;
191	    }
192	
193	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
194	    @Override
195	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
196	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
197	        if (currentOwner == null) {
198	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
199	        }
200	        currentOwner.setAddress(ownerFieldsDto.getAddress());
201	        currentOwner.setCity(ownerFieldsDto.getCity());
202	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
203	        currentOwner.setLastName(ownerFieldsDto.getLastName());
204	        currentOwner.setTelephone(TelephoneNormalizer.normalize(ownerFieldsDto.getTelephone()));
205	        currentOwner.setEmail(EmailNormalizer.normalize(ownerFieldsDto.getEmail()));
206	        this.clinicService.saveOwner(currentOwner);
207	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
208	    }
209	
210	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
211	    @Transactional
212	    @Override
213	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
214	        Owner owner = this.clinicService.findOwnerById(ownerId);
215	        if (owner == null) {
216	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
217	        }
218	        this.clinicService.deleteOwner(owner);
219	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
220	    }
221	
222	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
223	    @Override
224	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
225	        Owner owner = this.clinicService.findOwnerById(ownerId);
226	        if (owner == null) {
227	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
228	        }
229	        HttpHeaders headers = new HttpHeaders();
230	        Pet pet = petMapper.toPet(petFieldsDto);
231	        owner.setId(ownerId);
232	        pet.setOwner(owner);
233	        pet.getType().setName(null);
234	        this.clinicService.savePet(pet);
235	        PetDto petDto = petMapper.toPetDto(pet);
236	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
237	            .buildAndExpand(pet.getId()).toUri());
238	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
239	    }
240	
241	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
242	    @Override
243	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
244	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
245	        if (currentOwner != null) {
246	            Pet currentPet = this.clinicService.findPetById(petId);
247	            if (currentPet != null) {
248	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
249	                currentPet.setName(petFieldsDto.getName());
250	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
251	                this.clinicService.savePet(currentPet);
252	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
253	            }
254	        }
255	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
256	    }
257	
258	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
259	    @Override
260	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
261	        HttpHeaders headers = new HttpHeaders();
262	        Visit visit = visitMapper.toVisit(visitFieldsDto);
263	        Pet pet = new Pet();
264	        pet.setId(petId);
265	        visit.setPet(pet);
266	        this.clinicService.saveVisit(visit);
267	        VisitDto visitDto = visitMapper.toVisitDto(visit);
268	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
269	            .buildAndExpand(visit.getId()).toUri());
270	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
271	    }
272	
273	
274	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
275	    @Override
276	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
277	        Owner owner = this.clinicService.findOwnerById(ownerId);
278	        if (owner != null) {
279	            Pet pet = owner.getPet(petId);
280	            if (pet != null) {
281	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
282	            }
283	        }
284	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	    }
286	}
287

