17	package org.springframework.samples.petclinic.rest.advice;
18	
19	import java.net.URI;
20	import java.time.Instant;
21	import java.util.List;
22	import java.util.Objects;
23	
24	import jakarta.servlet.http.HttpServletRequest;
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.springframework.dao.DataIntegrityViolationException;
28	import org.springframework.http.HttpStatus;
29	import org.springframework.http.ProblemDetail;
30	import org.springframework.http.ResponseEntity;
31	import org.springframework.samples.petclinic.rest.controller.BindingErrorsResponse;
32	import org.springframework.samples.petclinic.rest.dto.ValidationMessageDto;
33	import org.springframework.samples.petclinic.rest.validation.CityCapacityExceededException;
34	import org.springframework.samples.petclinic.rest.validation.DailyOwnerLimitExceededException;
35	import org.springframework.samples.petclinic.rest.validation.DuplicateIdentityException;
36	import org.springframework.samples.petclinic.rest.validation.FutureRegistrationDateException;
37	import org.springframework.samples.petclinic.rest.validation.InvalidPostcodeException;
38	import org.springframework.samples.petclinic.rest.validation.InvalidTelephoneException;
39	import org.springframework.samples.petclinic.rest.validation.MissingOwnerFieldsException;
40	import org.springframework.security.access.AccessDeniedException;
41	import org.springframework.validation.BindingResult;
42	import org.springframework.validation.FieldError;
43	import org.springframework.web.bind.MethodArgumentNotValidException;
44	import org.springframework.web.bind.annotation.ControllerAdvice;
45	import org.springframework.web.bind.annotation.ExceptionHandler;
46	import org.springframework.web.bind.annotation.ResponseBody;
47	
48	/**
49	 * Global Exception handler for REST controllers.
50	 * <p>
51	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
52	 *
53	 * @author Vitaliy Fedoriv
54	 * @author Alexander Dudkin
55	 */
56	@ControllerAdvice
57	public class ExceptionControllerAdvice {
58	
59	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
60	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
61	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
62	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
63	    private static final String ERROR_DUPLICATE_IDENTITY = "An owner with the same identity already exists";
64	    private static final String ERROR_CITY_AT_CAPACITY = "The owner's city has already reached its maximum number of owners";
65	    private static final String ERROR_DAILY_LIMIT_REACHED = "The maximum number of owners that may be registered today has already been reached";
66	    private static final String ERROR_FUTURE_REGISTRATION_DATE = "The registration date must not be later than the server date";
67	
68	    /**
69	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
70	     * class.
71	     *
72	     * @param e     Object referring to the thrown exception.
73	     * @param status HTTP response status.
74	     * @param url URL request.
75	     */
76	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
77	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
78	        problemDetail.setType(URI.create(url.toString()));
79	        problemDetail.setTitle(e.getClass().getSimpleName());
80	        problemDetail.setDetail(detail);
81	        problemDetail.setProperty("timestamp", Instant.now());
82	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
83	        return problemDetail;
84	    }
85	
86	    /**
87	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
88	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
89	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
90	     * would catch it and report an authorization failure as a 500.
91	     *
92	     * @param e The {@link AccessDeniedException} to propagate
93	     * @throws AccessDeniedException always
94	     */
95	    @ExceptionHandler(AccessDeniedException.class)
96	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
97	        throw e;
98	    }
99	
100	    /**
101	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
102	     *
103	     * @param e The {@link Exception} to be handled
104	     * @param request {@link HttpServletRequest} object referring to the current request.
105	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
106	     */
107	    @ExceptionHandler(Exception.class)
108	    @ResponseBody
109	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
110	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
111	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
112	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
113	        return ResponseEntity.status(status).body(detail);
114	    }
115	
116	    /**
117	     * Handles {@link DataIntegrityViolationException} which typically indicates database constraint violations. This
118	     * method returns a 404 Not Found status if an entity does not exist.
119	     *
120	     * @param e The {@link DataIntegrityViolationException} to be handled
121	     * @param request {@link HttpServletRequest} object referring to the current request.
122	     * @return A {@link ResponseEntity} containing the error information and a 404 Not Found status
123	     */
124	    @ExceptionHandler(DataIntegrityViolationException.class)
125	    @ResponseBody
126	    public ResponseEntity<ProblemDetail> handleDataIntegrityViolationException(DataIntegrityViolationException e, HttpServletRequest request) {
127	        logger.warn("Data integrity violation at {} {}: {}",
128	            request.getMethod(),
129	            request.getRequestURI(),
130	            e.getMessage());
131	        logger.debug("Data integrity violation stacktrace", e);
132	        HttpStatus status = HttpStatus.NOT_FOUND;
133	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DATA_INTEGRITY);
134	        return ResponseEntity.status(status).body(detail);
135	    }
136	
137	    /**
138	     * Handles exception thrown by Bean Validation on controller methods parameters
139	     *
140	     * @param e The {@link MethodArgumentNotValidException} to be handled
141	     * @param request {@link HttpServletRequest} object referring to the current request.
142	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
143	     */
144	    @ExceptionHandler(MethodArgumentNotValidException.class)
145	    @ResponseBody
146	    public ResponseEntity<ProblemDetail> handleMethodArgumentNotValidException(MethodArgumentNotValidException e, HttpServletRequest request) {
147	        HttpStatus status = HttpStatus.BAD_REQUEST;
148	        BindingErrorsResponse errors = new BindingErrorsResponse();
149	        BindingResult bindingResult = e.getBindingResult();
150	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
151	        if (bindingResult.hasErrors()) {
152	            errors.addAllErrors(bindingResult);
153	            List<ValidationMessageDto> schemaValidationErrors = bindingResult.getFieldErrors().stream()
154	                .map(fieldError -> {
155	                    String rejectedValue = Objects.toString(fieldError.getRejectedValue(), "null");
156	                    String defaultMessage = Objects.toString(fieldError.getDefaultMessage(), "Validation failed");
157	                    String message = "Field '%s' %s (rejected value: %s)".formatted(
158	                        fieldError.getField(),
159	                        defaultMessage,
160	                        rejectedValue);
161	                    return new ValidationMessageDto(message)
162	                        .putAdditionalProperty("field", fieldError.getField())
163	                        .putAdditionalProperty("rejectedValue", rejectedValue)
164	                        .putAdditionalProperty("defaultMessage", defaultMessage);
165	                })
166	                .toList();
167	            logger.debug("Validation error at {} {}: {}",
168	                request.getMethod(),
169	                request.getRequestURI(),
170	                bindingResult.getFieldErrors());
171	            detail.setProperty("schemaValidationErrors", schemaValidationErrors);
172	            List<String> invalidFields = bindingResult.getFieldErrors().stream()
173	                .map(FieldError::getField)
174	                .distinct()
175	                .toList();
176	            detail.setProperty("errors", invalidFields);
177	            return ResponseEntity.status(status).body(detail);
178	        }
179	        return ResponseEntity.status(status).body(detail);
180	    }
181	
182	    /**
183	     * Handles {@link MissingOwnerFieldsException} raised when a request to create or update an owner
184	     * omits one or more mandatory fields, returning a 400 Bad Request whose {@code errors} array lists
185	     * the name of each missing field.
186	     *
187	     * @param e The {@link MissingOwnerFieldsException} to be handled
188	     * @param request {@link HttpServletRequest} object referring to the current request.
189	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
190	     */
191	    @ExceptionHandler(MissingOwnerFieldsException.class)
192	    @ResponseBody
193	    public ResponseEntity<ProblemDetail> handleMissingOwnerFieldsException(MissingOwnerFieldsException e, HttpServletRequest request) {
194	        HttpStatus status = HttpStatus.BAD_REQUEST;
195	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
196	        detail.setProperty("errors", e.getFields());
197	        return ResponseEntity.status(status).body(detail);
198	    }
199	
200	    /**
201	     * Handles {@link InvalidTelephoneException} raised when a submitted telephone number cannot be
202	     * converted to a valid E.164 value, returning a 400 Bad Request.
203	     *
204	     * @param e The {@link InvalidTelephoneException} to be handled
205	     * @param request {@link HttpServletRequest} object referring to the current request.
206	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
207	     */
208	    @ExceptionHandler(InvalidTelephoneException.class)
209	    @ResponseBody
210	    public ResponseEntity<ProblemDetail> handleInvalidTelephoneException(InvalidTelephoneException e, HttpServletRequest request) {
211	        HttpStatus status = HttpStatus.BAD_REQUEST;
212	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
213	        detail.setProperty("errors", List.of("telephone"));
214	        return ResponseEntity.status(status).body(detail);
215	    }
216	
217	    /**
218	     * Handles {@link InvalidPostcodeException} raised when a supplied postcode is out of range for
219	     * its city's region, returning a 400 Bad Request.
220	     *
221	     * @param e The {@link InvalidPostcodeException} to be handled
222	     * @param request {@link HttpServletRequest} object referring to the current request.
223	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
224	     */
225	    @ExceptionHandler(InvalidPostcodeException.class)
226	    @ResponseBody
227	    public ResponseEntity<ProblemDetail> handleInvalidPostcodeException(InvalidPostcodeException e, HttpServletRequest request) {
228	        HttpStatus status = HttpStatus.BAD_REQUEST;
229	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_INVALID_REQUEST);
230	        detail.setProperty("errors", List.of("postcode"));
231	        return ResponseEntity.status(status).body(detail);
232	    }
233	
234	    /**
235	     * Handles {@link DuplicateIdentityException} raised when a new owner's identity key (normalized
236	     * telephone, email and household id) exactly matches that of an existing owner, returning a 409
237	     * Conflict.
238	     *
239	     * @param e The {@link DuplicateIdentityException} to be handled
240	     * @param request {@link HttpServletRequest} object referring to the current request.
241	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
242	     */
243	    /**
244	     * Handles {@link FutureRegistrationDateException} raised when a supplied registration date is
245	     * later than the server's current date, returning a 400 Bad Request.
246	     *
247	     * @param e The {@link FutureRegistrationDateException} to be handled
248	     * @param request {@link HttpServletRequest} object referring to the current request.
249	     * @return A {@link ResponseEntity} containing the error information and a 400 Bad Request status.
250	     */
251	    @ExceptionHandler(FutureRegistrationDateException.class)
252	    @ResponseBody
253	    public ResponseEntity<ProblemDetail> handleFutureRegistrationDateException(FutureRegistrationDateException e, HttpServletRequest request) {
254	        HttpStatus status = HttpStatus.BAD_REQUEST;
255	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_FUTURE_REGISTRATION_DATE);
256	        detail.setProperty("errors", List.of("registrationDate"));
257	        return ResponseEntity.status(status).body(detail);
258	    }
259	
260	    @ExceptionHandler(DuplicateIdentityException.class)
261	    @ResponseBody
262	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
263	        HttpStatus status = HttpStatus.CONFLICT;
264	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_DUPLICATE_IDENTITY);
265	        detail.setProperty("errors", List.of("identityKey"));
266	        return ResponseEntity.status(status).body(detail);
267	    }
268	
269	    /**
270	     * Handles {@link CityCapacityExceededException} raised when a new owner is submitted for a city
271	     * that already holds the maximum number of owners, returning a 409 Conflict.
272	     *
273	     * @param e The {@link CityCapacityExceededException} to be handled
274	     * @param request {@link HttpServletRequest} object referring to the current request.
275	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status.
276	     */
277	    @ExceptionHandler(CityCapacityExceededException.class)
278	    @ResponseBody
279	    public ResponseEntity<ProblemDetail> handleCityCapacityExceededException(CityCapacityExceededException e, HttpServletRequest request) {
280	        HttpStatus status = HttpStatus.CONFLICT;
281	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_CITY_AT_CAPACITY);
282	        detail.setProperty("errors", List.of("city"));
283	        return ResponseEntity.status(status).body(detail);
284	    }
285	
286	    /**
287	     * Handles {@link DailyOwnerLimitExceededException} raised when the maximum number of owners
288	     * allowed to be registered on a single day has already been reached, returning a 429 Too Many
289	     * Requests.
290	     *
291	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
292	     * @param request {@link HttpServletRequest} object referring to the current request.
293	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status.
294	     */
295	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
296	    @ResponseBody
297	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
